package com.m3.arrays;

/**
 * Shared M3 SDK scaffold marker of this module: thrown by every scaffold member whose
 * behaviour (atom) has not yet been received from its Synexia MIndex donor.
 *
 * <p>Generated by {@code com.synexia.rewrite.M3MIndexScaffoldSkeletonRecipe}; donor lineage
 * per scaffold is recorded in {@code m3/compatibility/MINDEX_TO_M3_SCAFFOLD_LEDGER.tsv}.
 */
public final class M3NotYetReceived extends UnsupportedOperationException {
    private static final long serialVersionUID = 1L;

    /**
     * Creates the marker for one scaffold member.
     *
     * @param member scaffold member id, {@code Owner#member/arity}
     */
    public M3NotYetReceived(String member) {
        super("M3 scaffold: atom not yet received: " + member);
    }
}
